old=(R.parents[1]/'F04-03/v01/source/charger-preview.js').read_text();draw=old[old.index('function drawModel'):old.index('root.WildcraftChargerPreview=')]
draw=draw.replace('present=true,state=2','node=-1').replace('makeFaces(geo,energy,present,state)','makeFaces(geo,energy,node)').replace('x-=8;y-=8;z-=8;','y-=5.2;').replace('p[0]*22/320','p[0]*18/320').replace('p[1]*22/225','p[1]*18/225').replace('-p[2]/16','-p[2]/32').replace('batteryCuboids:present?geo.batteryParts.length:0,state,present','batteryCuboids:node>=0?geo.batteryParts.length:0,node,referenceScale:1')
