make=r'''function fractions(e){const q=Math.max(0,Math.min(1000,e))/1000*3;return [0,1,2].map(i=>Math.max(0,Math.min(1,q-i)));}
function rotate(v,n){const [x,y,z]=v;return [[x,z,-y],[x,-z,y],[-x,y,-z],[x,y,z],[-z,y,x],[z,y,-x]][n];}
function point(v,n,g){return n===undefined?v:rotate(v,n).map((a,i)=>a+g.nodes[n].point[i]);}
function makeFaces(geo,e,node=-1){const faces=[],normals={north:[0,0,-1],south:[0,0,1],west:[-1,0,0],east:[1,0,0],up:[0,1,0],down:[0,-1,0]};
for(const p of [...geo.parts,...(node>=0?geo.batteryParts.map(p=>({...p,node})):[])]){const [x0,y0,z0]=p.from,[x1,y1,z1]=p.to;const v={south:[[x1,y1,z1],[x0,y1,z1],[x0,y0,z1],[x1,y0,z1]],north:[[x0,y1,z0],[x1,y1,z0],[x1,y0,z0],[x0,y0,z0]],west:[[x0,y1,z1],[x0,y1,z0],[x0,y0,z0],[x0,y0,z1]],east:[[x1,y1,z0],[x1,y1,z1],[x1,y0,z1],[x1,y0,z0]],up:[[x0,y1,z1],[x1,y1,z1],[x1,y1,z0],[x0,y1,z0]],down:[[x0,y0,z0],[x1,y0,z0],[x1,y0,z1],[x0,y0,z1]]};for(const [dir,points] of Object.entries(v))faces.push({name:p.name,vertices:points.map(v=>point(v,p.node,geo)),normal:p.node===undefined?normals[dir]:rotate(normals[dir],p.node),uv:p.faces[dir].uv});}
if(node>=0)for(const w of geo.batteryWindows){const a=fractions(e)[w.indexBottomUp];if(a>0){const [x0,y0,z]=w.from,[x1,ymax]=w.to,y1=y0+(ymax-y0)*a;const [u0,v0,u1,v1]=geo.batteryEnergyUV;faces.push({name:'energy/'+w.indexBottomUp,vertices:[[x1,y1,z],[x0,y1,z],[x0,y0,z],[x1,y0,z]].map(v=>point(v,node,geo)),normal:rotate([0,0,1],node),uv:[u0,v0+(v1-v0)*(1-a),u1,v1]});}}return faces;}
function project(v,yaw,pitch,fit={scale:18,cx:0,cy:0}){const ya=yaw*Math.PI/180,pa=pitch*Math.PI/180,cy=Math.cos(ya),sy=Math.sin(ya),cp=Math.cos(pa),sp=Math.sin(pa),[x,yy,z]=v,y=yy-5.2,xx=x*cy+z*sy,zz=z*cy-x*sy;return [320-(xx-fit.cx)*fit.scale,225+(-y*cp+zz*sp-fit.cy)*fit.scale];}
'''
